#include <iostream>
#include <vector>

bool lote_valido(const std::vector<int>& pedidos) {
    if (pedidos.size() > 6) {
        return false;
    }
    for (int cantidad : pedidos) {
        if ((cantidad < 0) || (cantidad > 20)) {
            return false;
        }
    }
    return true;
}

bool capacidad_valida(int capacidad) {
    return (capacidad >= 1) && (capacidad <= 10);
}

int total_unidades(const std::vector<int>& pedidos) {
    int total = 0;
    for (int cantidad : pedidos) {
        total = total + cantidad;
    }
    return total;
}

int contenedores_necesarios(int total, int capacidad) {
    int contenedores = total / capacidad;
    if (total % capacidad != 0) {
        ++contenedores;
    }
    return contenedores;
}

void mostrar_plan(int total, int contenedores) {
    std::cout << "Unités : " << total << "\n";
    std::cout << "Conteneurs : " << contenedores;
}

int main() {
    const std::vector<int> pedidos = {3, 4, 5};
    const int capacidad = 5;
    if (lote_valido(pedidos) && capacidad_valida(capacidad)) {
        const int total = total_unidades(pedidos);
        const int contenedores = contenedores_necesarios(total, capacidad);
        mostrar_plan(total, contenedores);
    } else {
        std::cout << "Données hors domaine";
    }
    return 0;
}

